GET /ipd/my-beds.typescript_example:
// Ward nurse: my rostered beds this shift (doses due, last vitals)  (permissions: ipd.flowsheet.record)
export const myBeds = () =>
  api("GET", `/ipd/my-beds`, undefined);   // api(): see get_guide('envelope-and-errors')

GET /self/roster.typescript_example:
// My duties (two weeks from today by default)  (permissions: self.profile.view)
export const myDuties = () =>
  api("GET", `/self/roster`, undefined);   // api(): see get_guide('envelope-and-errors')

POST /beds/{bed_id}/mark-cleaned.typescript_example:
// Confirm a bed was cleaned (where no badge station records it)  (permissions: ipd.bed.mark_cleaned)
export const markCleaned = (bed_id, body) =>
  api("POST", `/beds/${bed_id}/mark-cleaned`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

GET /admissions/{admission_id}/discharge.typescript_example:
// Printable discharge summary, or referral slip for a transfer  (permissions: ipd.discharge.initiate, clinical.encounter.view, patient.emr.view)
export const dischargeSummaryPrint = (admission_id) =>
  api("GET", `/admissions/${admission_id}/discharge-summary/print-payload`, undefined);   // api(): see get_guide('envelope-and-errors')

// The signed discharge summary as a PDF  (permissions: ipd.discharge.initiate, clinical.encounter.view, patient.emr.view)
export const dischargeSummaryPdf = (admission_id) =>
  api("GET", `/admissions/${admission_id}/discharge-summary/pdf`, undefined);   // api(): see get_guide('envelope-and-errors')

